parameters.blocksUi:
={{
(() => {
  const raw = $json.output || [];
  const stories = Array.isArray(raw) ? raw : [raw];

  const clean = (text = "") =>
    String(text)
      .replace(/\s+/g, " ")
      .replace(/\s*\S?cite(?:\S*turn\d+\w+\d+)+\S*/g, "")
      .trim();

  const truncate = (text = "", max = 180) => {
    const t = clean(text);
    return t.length > max ? `${t.slice(0, max - 1).trim()}…` : t;
  };

  const severityEmoji = {
    CANARY: ":white_circle:",
    NOTABLE: ":large_yellow_circle:",
    SIGNIFICANT: ":large_orange_circle:",
    CRITICAL: ":red_circle:",
    EXISTENTIAL: ":black_circle:"
  };

  const currentClock =
    stories.length ? stories[stories.length - 1].updated_clock_position || "UNKNOWN" : "UNKNOWN";

  const movedStories = stories.filter(s => {
    const n = parseInt(String(s.clock_delta_label || "").match(/-?\d+/)?.[0] || "0", 10);
    return n > 0;
  });

  const severityCounts = stories.reduce((acc, story) => {
    const key = story.severity_label || "UNKNOWN";
    acc[key] = (acc[key] || 0) + 1;
    return acc;
  }, {});

  const severitySummary = ["EXISTENTIAL", "CRITICAL", "SIGNIFICANT", "NOTABLE", "CANARY"]
    .filter(label => severityCounts[label])
    .map(label => `${severityEmoji[label] || ""} ${label} ${severityCounts[label]}`)
    .join("   ");

  if (!stories.length) {
    return {
      blocks: [
        {
          type: "header",
          text: {
            type: "plain_text",
            text: "Skynet Countdown",
            emoji: true
          }
        },
        {
          type: "section",
          text: {
            type: "mrkdwn",
            text: "*No qualifying incidents were produced in this run.*"
          }
        }
      ]
    };
  }

  return {
    blocks: [
      {
        type: "header",
        text: {
          type: "plain_text",
          text: "Skynet Countdown",
          emoji: true
        }
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text:
            `*Clock position:* ${currentClock}\n` +
            `*Incidents logged:* ${stories.length}  •  *Clock-moving events:* ${movedStories.length}`
        }
      },
      ...(severitySummary
        ? [{
            type: "context",
            elements: [
              {
                type: "mrkdwn",
                text: severitySummary
              }
            ]
          }]
        : []),
      {
        type: "divider"
      },
      ...stories.slice(0, 5).flatMap((story, index) => {
        const emoji = severityEmoji[story.severity_label] || ":small_blue_diamond:";
        const take = truncate(story.our_take, 190);
        const meta = truncate(story.metadata_line, 140);

        const blocks = [
          {
            type: "section",
            text: {
              type: "mrkdwn",
              text:
                `${emoji} *${story.severity_label || "UNKNOWN"}*  ·  *${story.headline || "Untitled"}*\n` +
                `_${meta}_\n` +
                `>${take}`
            }
          },
          {
            type: "context",
            elements: [
              {
                type: "mrkdwn",
                text:
                  `${story.cve_id || "NO-ID"}  •  ${story.clock_delta_label || "+0 MINUTES"}  •  Clock now ${story.updated_clock_position || currentClock}`
              }
            ]
          }
        ];

        if (index < Math.min(stories.length, 5) - 1) {
          blocks.push({ type: "divider" });
        }

        return blocks;
      }),
      ...(stories.length > 5
        ? [
            {
              type: "section",
              text: {
                type: "mrkdwn",
                text: `_…and ${stories.length - 5} more incident${stories.length - 5 === 1 ? "" : "s"} in the full run._`
              }
            }
          ]
        : [])
    ]
  };
})()
}}

