// Connect this node DIRECTLY to AI Agent Writer.
// Run Once for All Items. Never match by array position or model-generated ID.
return $input.all().map((item, index) => {
  const d = $('AI Agent Scorer').itemMatching(index).json.output;
  const story = item.json.output;
  if (!d || typeof d !== 'object' || typeof d.source_url !== 'string' || !d.source_url.trim()) {
    throw new Error('No linked assessment with a source URL. Connect this node directly to AI Agent Writer and preserve item links.');
  }
  if (!story || typeof story !== 'object' || Array.isArray(story)) {
    throw new Error('Expected the structured writer output in item.json.output.');
  }
  const assessment = {
      cve_id:                           d.cve_id,
      incident_title:                   d.incident_title,
      incident_date:                    d.incident_date,
      source_url:                       d.source_url,
      classification:                   d.classification,
      total_score:                      d.total_score,
      clock_delta_minutes:              d.clock_delta_minutes,
      full_trifecta:                    d.trifecta?.full_trifecta,
      t1_score:                         d.trifecta?.t1?.score,
      t1_rationale:                     d.trifecta?.t1?.rationale,
      t2_score:                         d.trifecta?.t2?.score,
      t2_rationale:                     d.trifecta?.t2?.rationale,
      t3_score:                         d.trifecta?.t3?.score,
      t3_rationale:                     d.trifecta?.t3?.rationale,
      amp_governance_vacuum_score:      d.amplifiers?.governance_vacuum?.score,
      amp_governance_vacuum_rationale:  d.amplifiers?.governance_vacuum?.rationale,
      amp_autonomy_score:               d.amplifiers?.autonomy_without_oversight?.score,
      amp_autonomy_rationale:           d.amplifiers?.autonomy_without_oversight?.rationale,
      amp_capability_erosion_score:     d.amplifiers?.human_capability_erosion?.score,
      amp_capability_erosion_rationale: d.amplifiers?.human_capability_erosion?.rationale,
      amp_sentience_score:              d.amplifiers?.sentience_self_preservation?.score,
      amp_sentience_rationale:          d.amplifiers?.sentience_self_preservation?.rationale,
      amp_physical_score:               d.amplifiers?.physical_weaponisation?.score,
      amp_physical_rationale:           d.amplifiers?.physical_weaponisation?.rationale,
      is_leading_indicator:             d.is_leading_indicator,
      leading_indicator_note:           d.leading_indicator_note,
      scoring_notes:                    d.scoring_notes,
  };
  return {
    json: { assessment, story },
    pairedItem: { item: index },
  };
});
